create unique index if not exists seller_ledger_reference_uidx on public.seller_ledger_entries(reference) where reference is not null;
create or replace function public.refresh_seller_daily_metrics(p_seller_id uuid,p_metric_date date) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare v_orders integer;v_units integer;v_sales numeric;v_refunds numeric;v_commission numeric;v_cancelled integer;v_total integer;v_rating numeric;begin select count(distinct o.id),coalesce(sum(oi.quantity),0),coalesce(sum(oi.total_price),0) into v_orders,v_units,v_sales from public.order_items oi join public.orders o on o.id=oi.order_id where oi.seller_id=p_seller_id and o.status='delivered' and o.created_at::date=p_metric_date;select count(distinct o.id) filter(where o.status='cancelled'),count(distinct o.id) into v_cancelled,v_total from public.order_items oi join public.orders o on o.id=oi.order_id where oi.seller_id=p_seller_id and o.created_at::date=p_metric_date;select coalesce(avg(r.rating),0) into v_rating from public.reviews r join public.products p on p.id=r.product_id where p.seller_id=p_seller_id and r.is_published=true;select coalesce(sum(abs(e.amount)) filter(where e.entry_type='refund'),0),coalesce(sum(abs(e.amount)) filter(where e.entry_type='commission'),0) into v_refunds,v_commission from public.seller_ledger_entries e where e.seller_id=p_seller_id and e.created_at::date=p_metric_date;insert into public.seller_metrics_daily(seller_id,metric_date,orders_count,units_sold,gross_sales,refunds,commission,rating_average,cancellation_rate,fulfillment_rate) values(p_seller_id,p_metric_date,v_orders,v_units,v_sales,v_refunds,v_commission,v_rating,case when v_total=0 then 0 else round(v_cancelled::numeric/v_total*100,2) end,case when v_total=0 then 0 else round(v_orders::numeric/v_total*100,2) end) on conflict(seller_id,metric_date) do update set orders_count=excluded.orders_count,units_sold=excluded.units_sold,gross_sales=excluded.gross_sales,refunds=excluded.refunds,commission=excluded.commission,rating_average=excluded.rating_average,cancellation_rate=excluded.cancellation_rate,fulfillment_rate=excluded.fulfillment_rate,updated_at=now();end$$;
create or replace function public.on_order_status_finance_metrics() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ declare x record;v_commission numeric;begin if new.status=old.status then return new;end if;if new.status='delivered' then for x in select oi.id,oi.seller_id,oi.quantity,oi.total_price,s.commission_rate from public.order_items oi join public.sellers s on s.id=oi.seller_id where oi.order_id=new.id loop v_commission:=round(x.total_price*coalesce(x.commission_rate,0)/100,2);insert into public.seller_ledger_entries(seller_id,order_item_id,entry_type,amount,currency,description,reference) select x.seller_id,x.id,'sale',x.total_price,new.currency,'Delivered order sale',x.id::text||':sale' where not exists(select 1 from public.seller_ledger_entries e where e.reference=x.id::text||':sale');if v_commission>0 then insert into public.seller_ledger_entries(seller_id,order_item_id,entry_type,amount,currency,description,reference) select x.seller_id,x.id,'commission',-v_commission,new.currency,'Marketplace commission',x.id::text||':commission' where not exists(select 1 from public.seller_ledger_entries e where e.reference=x.id::text||':commission');end if;perform public.refresh_seller_daily_metrics(x.seller_id,new.created_at::date);end loop;elsif new.status='cancelled' then for x in select distinct seller_id from public.order_items where order_id=new.id loop perform public.refresh_seller_daily_metrics(x.seller_id,new.created_at::date);end loop;end if;return new;end$$;
drop trigger if exists trg_order_status_finance_metrics on public.orders;create trigger trg_order_status_finance_metrics after update of status on public.orders for each row execute function public.on_order_status_finance_metrics();
revoke all on function public.refresh_seller_daily_metrics(uuid,date) from public;revoke all on function public.on_order_status_finance_metrics() from public;